function hStrip(s){ return s.replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim(); }
function htmlToMd(src){
  var s=String(src||'');
  s=s.replace(/<script[\s\S]*?<\/script>/gi,''); s=s.replace(/<style[\s\S]*?<\/style>/gi,'');
  s=s.replace(/<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi, function(_,n,c){ return Array(+n+1).join('#')+' '+hStrip(c)+'\n'; });
  s=s.replace(/<(strong|b)>([\s\S]*?)<\/\1>/gi, function(_,_,c){ return '**'+hStrip(c)+'**'; });
  s=s.replace(/<(em|i)>([\s\S]*?)<\/\1>/gi, function(_,_,c){ return '*'+hStrip(c)+'*'; });
  s=s.replace(/<code>([\s\S]*?)<\/code>/gi, function(_,c){ return '`'+hStrip(c)+'`'; });
  s=s.replace(/<a[^>]*href="([^"]*)"[^>]*>([\s\S]*?)<\/a>/gi, function(_,u,c){ return '['+hStrip(c)+']('+u+')'; });
  s=s.replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, function(_,c){ return '- '+hStrip(c)+'\n'; });
  s=s.replace(/<\/ul>/gi,'\n'); s=s.replace(/<br\s*\/?>/gi,'\n');
  s=s.replace(/<p[^>]*>([\s\S]*?)<\/p>/gi, function(_,c){ return hStrip(c)+'\n\n'; });
  s=s.replace(/<[^>]+>/g,'');
  s=s.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&nbsp;/g,' ');
  return s.replace(/\n{3,}/g,'\n\n').trim();
}

var EXPORTS={htmlToMd:htmlToMd};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HtmlToMarkdownForgePure = EXPORTS; }
